//
// ChaCha20 (RFC 8439) keystream generator. Used to produce random overwrite
// data that can be regenerated byte-for-byte at any offset for verification
// (so a verify pass never needs the data kept in memory).
#pragma once

#include <array>
#include <cstddef>
#include <cstdint>

namespace platter {

class ChaCha20 {
public:
    using Key = std::array<std::uint8_t, 32>;
    using Nonce = std::array<std::uint8_t, 12>;

    ChaCha20(const Key& key, const Nonce& nonce) noexcept;

    // Writes `length` bytes of keystream starting at stream byte `offset`
    // (any offset, any length).
    void generate(std::uint64_t offset, std::uint8_t* out, std::size_t length) const noexcept;

    // Fresh key and nonce from the operating system's entropy source.
    static Key random_key();
    static Nonce random_nonce();

private:
    void block(std::uint64_t block_index, std::uint8_t out[64]) const noexcept;
    std::array<std::uint32_t, 16> state_{};
};

}  // namespace platter
